-- ----------------------------
-- Table structure for aimodel
-- ----------------------------
DROP TABLE IF EXISTS `aimodel`;
CREATE TABLE `aimodel`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '模型ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '模型描述',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型图标URL',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型分类：recommend/office/writing/life/education/entertainment',
  `prompt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型的系统提示词',
  `source` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型来源/作者',
  `tags` json NULL COMMENT '模型标签（JSON数组）',
  `isOfficial` tinyint(1) NULL DEFAULT 0 COMMENT '是否官方模型：0-否，1-是',
  `isActive` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用：0-禁用，1-启用',
  `sortOrder` int(11) NULL DEFAULT 0 COMMENT '排序权重，数值越大越靠前',
  `usageCount` bigint(20) NULL DEFAULT 0 COMMENT '使用次数',
  `creatorId` bigint(20) NULL DEFAULT NULL COMMENT '创建者ID',
  `createTime` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  `isDeleted` tinyint(1) NULL DEFAULT 0 COMMENT '是否删除：0-否，1-是',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_category`(`category`) USING BTREE,
  INDEX `idx_isActive`(`isActive`) USING BTREE,
  INDEX `idx_isOfficial`(`isOfficial`) USING BTREE,
  INDEX `idx_sortOrder`(`sortOrder`) USING BTREE,
  INDEX `idx_creatorId`(`creatorId`) USING BTREE,
  INDEX `idx_createTime`(`createTime`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI模型表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of aimodel
-- ----------------------------

