  `categoryName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分类名称',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '分类描述',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '分类图标',
  `sortOrder` int(11) NULL DEFAULT 0 COMMENT '排序权重',
  `isActive` tinyint(1) NULL DEFAULT 1 COMMENT '是否启用',
  `createTime` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updateTime` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `categoryKey`(`categoryKey`) USING BTREE,
  INDEX `idx_sortOrder`(`sortOrder`) USING BTREE,
  INDEX `idx_isActive`(`isActive`) USING BTREE
