DROP TABLE IF EXISTS `conversation`;
CREATE TABLE `conversation`  (
  `conversationId` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `userId` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `aiId` varchar(255) CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL,
  `startTime` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `endTime` datetime(0) NULL DEFAULT NULL,
  `conversationState` enum('active','completed') CHARACTER SET utf8 COLLATE utf8_unicode_ci NOT NULL DEFAULT 'active',
  `isDeleted` tinyint(1) NOT NULL DEFAULT 0,
  `createdTime` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedTime` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP(0),
  `description` varchar(1024) CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL,
  PRIMARY KEY (`conversationId`) USING BTREE,
  INDEX `idx_conversation_user_deleted`(`userId`, `isDeleted`, `createdTime`) USING BTREE,
  INDEX `idx_conversation_aiid`(`aiId`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_unicode_ci ROW_FORMAT = Dynamic;

