INSERT INTO `message` VALUES (1, 'dc51b813-09fb-447f-83da-bb3badab92f3', NULL, NULL, 'nihao', 'user', '2025-04-22 14:24:05', 0, NULL);
INSERT INTO `message` VALUES (2, 'dc51b813-09fb-447f-83da-bb3badab92f3', NULL, NULL, '你好！作为AI医生，我会尽力提供准确、严谨的信息和答案。请告诉我您的问题或疑问，我会根据现有的医学知识来帮助您。', 'ai', '2025-04-22 14:24:05', 0, NULL);
