INSERT INTO `message` VALUES (1915615271318454274, '1915030906700099585', 1, 'src/assets/doctor.png', '您好！您刚才提到自己是我的“大伯”，但如我之前所说，我作为一个AI助手，并没有实际的亲戚关系。如果您是想表达其他的含义或者有其他问题需要帮助，请告诉我更多信息，我会尽力为您提供支持和解答。', 'ai', '2025-04-25 11:54:05', 0, NULL);
