INSERT INTO `message` VALUES (1915616791074177025, '1915030906700099585', 2, 'src/assets/Mathematician.png', '您好！从之前的对话来看，您提到自己是我的“大伯”。如果您是在开玩笑或者进行某种特定的对话，请告诉我更多信息，这样我才能更好地理解和回应。\n\n如果您是在认真询问自己的身份，那么您就是那位与我进行对话的人。如果您有其他具体的问题或需要进一步的帮助，请告诉我更多的细节。', 'ai', '2025-04-25 12:00:08', 0, NULL);
