INSERT INTO `message` VALUES (1915751880210780162, '1915029821671403522', 1, 'src/assets/doctor.png', '你好！我是一个AI医生，我们之前没有见过面，所以我不清楚你是谁。你可以告诉我你的名字或者描述一下你的情况，这样我就能更好地帮助你了。如果你有任何健康方面的问题，也可以直接告诉我。', 'ai', '2025-04-25 20:56:55', 0, NULL);
