INSERT INTO `message` VALUES (1917125308910161921, '1915029821671403522', 1, 'doctor.png', '你是智普ai吗', 'user', '2025-04-29 15:54:26', 0, NULL);
INSERT INTO `message` VALUES (1917125309006630913, '1915029821671403522', 1, 'doctor.png', '是的，我是智谱AI，一个基于智谱 AI 公司训练的语言模型开发的人工智能助手。我的任务是针对用户的问题和要求提供适当的答复和支持。请问有什么可以帮助您的？', 'ai', '2025-04-29 15:54:26', 0, NULL);
INSERT INTO `message` VALUES (1917132647268622338, 'null', 1, 'doctor.png', '1', 'user', '2025-04-29 16:23:36', 0, NULL);
INSERT INTO `message` VALUES (1917132647822270465, 'null', 1, 'doctor.png', '您好，请问有什么医疗相关的问题我可以帮您解答吗？', 'ai', '2025-04-29 16:23:36', 0, NULL);
INSERT INTO `message` VALUES (1917132926567354370, 'null', 1, 'doctor.png', '1', 'user', '2025-04-29 16:24:42', 0, NULL);
INSERT INTO `message` VALUES (1917132926961618946, 'null', 1, 'doctor.png', '很抱歉，您的问题“1”比较模糊，请您提供更具体的信息或者详细描述您的问题，这样我才能更准确地为您提供帮助。', 'ai', '2025-04-29 16:24:42', 0, NULL);
INSERT INTO `message` VALUES (1917133436812824577, '1915030906700099585', 1, 'doctor.png', '1', 'user', '2025-04-29 16:26:44', 0, NULL);
INSERT INTO `message` VALUES (1917133437156757505, '1915030906700099585', 1, 'doctor.png', '您好，请问有什么健康问题或者医学相关的问题需要我帮助解答吗？我会尽我所能提供准确的信息。', 'ai', '2025-04-29 16:26:44', 0, NULL);
INSERT INTO `message` VALUES (1917144866412941313, '1917144865888653314', 1, 'doctor.png', '您好，请问有什么健康相关的问题我可以帮您解答吗？', 'ai', '2025-04-29 16:58:12', 0, NULL);
INSERT INTO `message` VALUES (1917145016510304258, '1917145016271228929', 1, 'doctor.png', 'nihao', 'user', '2025-04-29 17:12:45', 0, NULL);
INSERT INTO `message` VALUES (1917145016636133377, '1917145016581607426', 1, 'doctor.png', '您好！如果您有任何健康相关的问题或者需要医疗咨询，请随时告诉我，我会尽力提供帮助。', 'ai', '2025-04-29 17:12:45', 0, NULL);
INSERT INTO `message` VALUES (1917146298973278210, '1917146298579013633', 1, 'doctor.png', '如果您有任何健康相关的问题或者需要咨询，请详细描述您的情况或问题，我会根据您提供的信息给出建议。如果您只是发送了一个“1”，请提供更多的上下文或具体问题。', 'ai', '2025-04-29 17:17:51', 0, NULL);
INSERT INTO `message` VALUES (1917147724520628225, '1917147724071837697', 1, 'doctor.png', '1', 'user', '2025-04-29 16:58:12', 0, NULL);
