INSERT INTO `message` VALUES (2913920064734629889, '1915030906700099585', NULL, 'src/assets/doctor.png', '你好', 'user', '2025-04-22 15:01:56', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629890, '1915030906700099585', NULL, 'src/assets/Mathematician.png', '作为一名AI医生，我会遵循医学知识和最佳实践来回答问题。请随时提出你的医疗健康问题，我会尽我所能提供准确和严谨的信息。但请注意，我的回答不能替代专业医疗人员的诊断和治疗建议。如果你有健康问题，建议咨询医生或其他合格的医疗专家。', 'ai', '2025-04-22 15:01:56', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629891, '1915030906700099585', NULL, 'src/assets/Mathematician.png', 'nihao', 'user', '2025-04-22 15:47:42', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629892, '1915029821671403522', NULL, 'src/assets/Mathematician.png', '你好！作为AI医生，我会尽量提供准确、严谨的信息。请告诉我你的问题，我会在我能力范围内提供帮助。', 'ai', '2025-04-22 15:47:42', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629893, '1915029821671403522', 1, 'src/assets/doctor.png', 'nihao', 'user', '2025-04-22 15:53:53', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629894, '1915029821671403522', 1, 'src/assets/doctor.png', '你好！作为AI医生，我会尽力提供准确、严谨的医疗信息。如果你有任何医疗健康相关的问题，欢迎提问，我会根据现有的医学知识库为你解答。请注意，我的回答不能替代专业医生的诊断和建议。如果遇到紧急医疗情况，请及时联系专业医疗机构。', 'ai', '2025-04-22 15:53:53', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629895, '1915029821671403522', 1, 'src/assets/Mathematician.png', 'nhai', 'user', '2025-04-22 16:04:06', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629896, '1915029821671403522', 1, 'src/assets/doctor.png', '明白了，作为AI医生，我会提供基于现有医学知识严谨的回答。请问您有什么医疗健康方面的问题需要咨询？', 'ai', '2025-04-22 16:04:06', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629897, '1915029821671403522', 1, 'src/assets/doctor.png', '你是谁', 'user', '2025-04-22 16:06:47', 1, NULL);
INSERT INTO `message` VALUES (2913920064734629898, '1915029821671403522', 1, 'src/assets/doctor.png', '作为一名AI医生，我的角色是提供基于现有医学知识和数据的建议和信息。如果你有任何健康相关的问题，我会尽我所能提供帮助。但请记住，我是一个基于算法的AI，不能替代真实的医生，我的建议不能用于诊断或治疗任何医疗状况。如果你有具体的问题，请告诉我，我会根据现有的医学知识库提供尽可能准确的信息。', 'ai', '2025-04-22 16:06:47', 1, NULL);
